ALTER TABLE public.rooms ADD COLUMN IF NOT EXISTS scoring_patch text;
CREATE FUNCTION public._release_patch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.scoring_patch:='legal-reserve-1'; RETURN NEW; END $$;
CREATE TRIGGER release_patch BEFORE INSERT ON public.rooms FOR EACH ROW EXECUTE FUNCTION public._release_patch();
CREATE FUNCTION public._release_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='rooms' THEN IF length(NEW.name)>80 THEN RAISE EXCEPTION 'Room name too long'; END IF; ELSE IF length(NEW.nickname)>24 OR length(NEW.team_name)>30 OR NEW.color !~ '^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'Invalid team identity'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER release_room_name BEFORE INSERT OR UPDATE OF name ON public.rooms FOR EACH ROW EXECUTE FUNCTION public._release_identity_guard();
CREATE TRIGGER release_team_identity BEFORE INSERT OR UPDATE OF nickname,team_name,color ON public.participants FOR EACH ROW EXECUTE FUNCTION public._release_identity_guard();
CREATE FUNCTION public._release_player_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.name)>100 OR length(NEW.country)>60 OR NEW.base_price NOT BETWEEN 0.2 AND 1000 OR length(coalesce(NEW.photo_url,''))>4096 OR length(coalesce(NEW.photo_source,''))>4096 OR length(coalesce(NEW.photo_credit,''))>1000 THEN RAISE EXCEPTION 'Player fields out of bounds'; END IF; IF coalesce(NEW.photo_url,'')<>'' AND NEW.photo_url !~ '^https://' AND NEW.photo_url !~ '^/__l5e/assets-v1/' THEN RAISE EXCEPTION 'Photo must use HTTPS'; END IF; IF coalesce(NEW.photo_source,'')<>'' AND NEW.photo_source !~ '^https://' THEN RAISE EXCEPTION 'Source must use HTTPS'; END IF; RETURN NEW; END $$;
CREATE TRIGGER release_player BEFORE INSERT OR UPDATE ON public.players FOR EACH ROW EXECUTE FUNCTION public._release_player_guard();
CREATE FUNCTION public._release_notes_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.is_room_member(NEW.room_id) OR length(NEW.notes)>20000 OR octet_length(NEW.targets::text)>32768 OR octet_length(NEW.xi::text)>8192 THEN RAISE EXCEPTION 'Private notes out of bounds or wrong room'; END IF; RETURN NEW; END $$;
CREATE TRIGGER release_notes BEFORE INSERT OR UPDATE ON public.private_notes FOR EACH ROW EXECUTE FUNCTION public._release_notes_guard();
CREATE FUNCTION public._release_leadership_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.rationale)>10000 OR octet_length(NEW.sources::text)>32768 OR jsonb_array_length(NEW.sources)>20 OR NEW.cutoff>current_date THEN RAISE EXCEPTION 'Leadership evidence out of bounds'; END IF; RETURN NEW; END $$;
CREATE TRIGGER release_leadership BEFORE INSERT ON public.leadership_reviews FOR EACH ROW EXECUTE FUNCTION public._release_leadership_guard();
CREATE OR REPLACE FUNCTION public.propose_trade(p_room uuid,p_to uuid,p_offer uuid[],p_request uuid[],p_cash numeric,p_parent uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.rooms; me public.participants:=public._me(p_room); v uuid; BEGIN SELECT * INTO r FROM public.rooms WHERE id=p_room FOR UPDATE; IF r.status<>'trade' OR now()>=r.trade_ends_at THEN RAISE EXCEPTION 'Trade window is closed'; END IF; IF cardinality(p_offer)>25 OR cardinality(p_request)>25 OR abs(coalesce(p_cash,0))>100000 OR coalesce(p_cash,0)::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Trade out of bounds'; END IF; IF (SELECT count(*) FROM public.trades WHERE room_id=p_room AND from_participant=me.id AND created_at>now()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'Too many trades; wait a minute'; END IF; IF p_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.trades WHERE id=p_parent AND room_id=p_room AND to_participant=me.id AND from_participant=p_to) THEN RAISE EXCEPTION 'Invalid counter trade'; END IF; IF p_to=me.id OR NOT EXISTS(SELECT 1 FROM public.participants WHERE id=p_to AND room_id=p_room) THEN RAISE EXCEPTION 'Pick another team'; END IF; IF coalesce(cardinality(p_offer),0)=0 AND coalesce(cardinality(p_request),0)=0 THEN RAISE EXCEPTION 'Add at least one player'; END IF; IF (SELECT count(*) FROM public.squads WHERE participant_id=me.id AND player_id=ANY(p_offer))<>coalesce(cardinality(p_offer),0) THEN RAISE EXCEPTION 'You do not own all offered players'; END IF; IF (SELECT count(*) FROM public.squads WHERE participant_id=p_to AND player_id=ANY(p_request))<>coalesce(cardinality(p_request),0) THEN RAISE EXCEPTION 'They do not own all requested players'; END IF; INSERT INTO public.trades(room_id,from_participant,to_participant,offer_players,request_players,cash,parent_trade_id) VALUES(p_room,me.id,p_to,coalesce(p_offer,'{}'),coalesce(p_request,'{}'),coalesce(p_cash,0),p_parent) RETURNING id INTO v; PERFORM public._log(p_room,'trade',me.team_name||' proposed a trade'); RETURN v; END $$;
DO $$ DECLARE p record; d text; BEGIN FOR p IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('update_room_settings','set_pool','start_review','host_control','open_trades','transfer_host') LOOP d:=pg_get_functiondef(p.oid); d:=replace(d,'r.host_id <> auth.uid()','auth.uid() IS NULL OR r.host_id IS DISTINCT FROM auth.uid()'); IF p.proname='set_pool' THEN d:=replace(d,'s := r.settings;','IF cardinality(p_player_ids)>150 THEN RAISE EXCEPTION ''Pool out of bounds''; END IF; s := r.settings;'); END IF; EXECUTE d; END LOOP; END $$;
DO $$ DECLARE p record; d text; BEGIN FOR p IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='import_evidence_bundle' LOOP d:=pg_get_functiondef(p.oid); d:=replace(d,'snap:=p_bundle->''snapshot'';', 'IF octet_length(p_bundle::text)>31457280 OR jsonb_array_length(p_bundle->''players'') NOT BETWEEN 1 AND 500 OR jsonb_array_length(p_bundle->''matches'') NOT BETWEEN 1 AND 30000 OR jsonb_array_length(coalesce(p_bundle->''positions'',''[]''))>1500 THEN RAISE EXCEPTION ''Import out of bounds''; END IF; snap:=p_bundle->''snapshot'';'); EXECUTE d; END LOOP; END $$;
REVOKE EXECUTE ON FUNCTION public._release_patch(),public._release_identity_guard(),public._release_player_guard(),public._release_notes_guard(),public._release_leadership_guard() FROM PUBLIC,anon,authenticated;